Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML :

```cpp
#include <string>
#include <sstream>
#include <iostream>
#include <unordered_map>

// Fonction de conversion Markdown -> HTML
std::string convertMarkdownToHTML(const std::string& markdown) {
    // Tableau de correspondances entre les balises Markdown et HTML
    std::unordered_map<std::string, std::string> markdown_to_html {
        {"#","<h1>"},
        {"##","<h2>"},
        {"###","<h3>"},
        {"####","<h4>"},
        {"#####","<h5>"},
        {"######","<h6>"},
        {"*","<em>"},
        {"**","<strong>"},
        {"`","<code>"},
        {"[ ]","<input type=\"checkbox\">"},
        {"[x ]","<input type=\"checkbox\" checked>"},
        {"---","<hr>"},
        {"**_**","<b><i>"},
        {"*_**","<i><b>"},
        {"~~","<s>"}
    };

    std::stringstream html;
    bool in_list = false;
    bool in_code_block = false;

    // Boucle sur chaque caractère du texte Markdown
    for (char c : markdown) {
        std::string markdown_tag;
        std::string html_tag;

        // Récupération de la balise Markdown actuelle
        if (c == '#') {
            markdown_tag = c;
            while (markdown[tag_pos + 1] == '#') {
                markdown_tag += markdown[tag_pos + 1];
                tag_pos++;
            }
        }
        else if (c == '[' && markdown[tag_pos + 1] == ' ' && markdown[tag_pos + 2] == ']') {
            markdown_tag = "[ ]";
            tag_pos += 2;
            if (markdown[tag_pos] == 'x' && markdown[tag_pos + 1] == ' ') {
                markdown_tag = "[x ]";
                tag_pos += 2;
            }
        }
        else if (c == '*') {
            markdown_tag = c;
            while (markdown[tag_pos] == '*' || markdown[tag_pos] == '_') {
                markdown_tag += markdown[tag_pos];
                tag_pos++;
            }
        }
        else if (c == '`') {
            in_code_block = !in_code_block;
            continue;
        }
        else if (c == '|') {
            if (!in_list) {
                in_list = true;
                html << "<ul>";
            }
            else {
                html << "</li>";
                html << "<li>";
            }
            continue;
        }
        else if (c == '-') && (markdown[tag_pos + 1] == '-' && markdown[tag_pos + 2] == '-')) {
            html << "<hr>";
            continue;
        }
        else {
            markdown_tag = std::string(1, c);
        }

        // Récupération de la balise HTML correspondante
        auto it = markdown_to_html.find(markdown_tag);
        if (it != markdown_to_html.end()) {
            html_tag = it->second;
        }
        else {
            html_tag = markdown_tag;
        }

        // Ajout du contenu dans le flux de sortie HTML
        if (in_list) {
            html << "<li>";
        }
        if (in_code_block) {
            html << "<pre><code>";
            in_code_block = false;
        }
        html << html_tag;
        tag_pos++;
        if (in_code_block) {
            html << "</code></pre>";
        }
        if (in_list) {
            html << "</li>";
        }
    }

    if (in_list) {
        html << "</ul>";
    }

    return html.str();
}
```

Cette fonction utilise une table de correspondance entre les balises Markdown et HTML, ainsi qu'un flux de sortie stringstream pour générer le texte HTML.

Le code utilise des conditions if/else pour détecter les balises Markdown spécifiques et générer les balises HTML correspondantes.

Des booléens sont utilisés pour gérer le formatage des listes et des blocs de code.

Remarque importante : cette fonction ne couvre qu'une partie des conversions Markdown -> HTML. Pour une implémentation complète, vous pouvez utiliser une bibliothèque de conversion Markdown, telles que `puglerville` ou `doxygen`.

