Voici un programme C++ qui lit un fichier texte ligne par ligne et compte le nombre d'occurrences d'un mot spécifique dans le fichier :

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string word; // mot à chercher
    int count = 0; // compteur d'occurrences

    // Demander l'entrée du mot à chercher
    cout << "Entrez le mot à chercher : ";
    cin >> word;

    // Ouvrir le fichier pour lecture
    string filename;
    cout << "Entrez le nom du fichier à lire : ";
    cin >> filename;
    ifstream file(filename);

    if (!file) {
        cerr << "Erreur : Impossible d'ouvrir le fichier " << filename << endl;
        return 1;
    }

    // Lire le contenu du fichier ligne par ligne
    string line;
    while (getline(file, line)) {
        // Convertir la ligne en petit majuscule pour ignorer la casse
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Compter le nombre d'occurrences du mot dans la ligne
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            count++;
            pos += word.length(); // Avancer le pointeur de recherche
        }
    }

    // Fermer le fichier
    file.close();

    // Afficher le nombre d'occurrences du mot dans le fichier
    cout << "Le mot \"" << word << "\" apparait " << count << " fois dans le fichier " << filename << endl;

    return 0;
}
```

Le programme demande l'entrée du mot à chercher et du nom du fichier à lire, puis lit le contenu du fichier ligne par ligne en convertissant chaque ligne en petit majuscule pour ignorer la casse. Pour chaque ligne, il cherche l'occurrence du mot en utilisant la fonction `find` de la bibliothèque de chaînes de caractères C++.

